package com.termux.app.workspace;
import android.app.*;import android.os.Looper;import android.view.*;import android.widget.*;import android.text.Spanned;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentProjectPanelTest {
 TermuxActivity a;AgentProjectPanel panel;boolean alive=true;AtomicInteger reads=new AtomicInteger(),opens=new AtomicInteger(),jumps=new AtomicInteger(),pages=new AtomicInteger();List<JSONObject> history=new ArrayList<>();String location;
 @Before public void setup(){a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);}
 @After public void end(){if(panel!=null)panel.close();a.finish();}
 JSONObject row(String key,String kind)throws Exception{return new JSONObject().put("key",key).put("message",key).put("kind",kind);}
 AgentProjectPanel.Chat chat=new AgentProjectPanel.Chat(){public boolean valid(){return alive;}public List<JSONObject> rows(){return history;}public boolean hasOlder(){return true;}public void older(){pages.incrementAndGet();}public void open(JSONObject f){opens.incrementAndGet();}public boolean jump(String k){jumps.incrementAndGet();return true;}public void observe(Runnable r){}public void close(){alive=false;}};
 AgentProjectPanel.Backend backend=new AgentProjectPanel.Backend(){public byte[] read(String s,int max){reads.incrementAndGet();return s.contains("rev-parse")?("OK\0/artificial\0"+String.join("",Collections.nCopies(40,"a"))+"\0 M a.txt\0?? new.bin\0").getBytes(java.nio.charset.StandardCharsets.UTF_8):s.contains("--numstat")?"TEXT\n-old\n+new\n".getBytes():"MISSING".getBytes();}public void close(){}};
 View text(View root,String t){if(root instanceof TextView&&t.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=text(((ViewGroup)root).getChildAt(i),t);if(v!=null)return v;}return null;}
 void idle()throws Exception{for(int n=0;n<40;n++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(5);}}
 void check(String agent)throws Exception{for(String lang:new String[]{"ru","en"}){alive=true;WorkspaceLanguage.select(a,lang);WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent.equals("codex")?"codex":"ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";history.clear();history.add(row("user","attachment").put("attachment",new JSONObject().put("id","0123456789abcdef0123456789abcdef").put("name","long unavailable file name.zip").put("path","/fake/file.zip").put("bytes",123)));history.add(row("agent","text").put("body","[file](</fake/from agent.log>)"));panel=new AgentProjectPanel(a,p,"/artificial",chat,backend);LinearLayout existing=new LinearLayout(a);existing.setTag("existing-file-manager");View root=panel.wrap(existing,b->{},path->location=path);assertSame(existing,panel.content.getChildAt(0));assertEquals(lang.equals("ru")?0:1,pages.get());panel.select(1);idle();String all=lang.equals("ru")?"Все":"All",mine=lang.equals("ru")?"От вас":"From you",agentFilter=lang.equals("ru")?"От агента":"From agent";assertNotNull(text(root,all));assertNotNull(text(root,"long unavailable file name.zip"));assertNotNull(text(root,"from agent.log"));assertNotNull(text(root,lang.equals("ru")?"Файл недоступен; запись сохранена":"File unavailable; record retained"));text(root,mine).performClick();assertNotNull(text(root,"long unavailable file name.zip"));assertNull(text(root,"from agent.log"));text(root,agentFilter).performClick();assertNull(text(root,"long unavailable file name.zip"));assertEquals(View.GONE,text(root,lang.equals("ru")?"Открыть":"Open").getVisibility());assertEquals(0,opens.get());text(root,lang.equals("ru")?"Расположение":"Location").performClick();assertEquals("/fake",location);assertEquals(0,panel.selected);panel.select(1);text(root,lang.equals("ru")?"К сообщению":"Go to message").performClick();panel.select(2);idle();assertNotNull(text(root,"a.txt"));root.findViewWithTag("project-change-a.txt").performClick();idle();View diff=text(root,"-old\n+new\n");assertNotNull(diff);assertEquals(2,((Spanned)((TextView)diff).getText()).getSpans(0,((TextView)diff).length(),android.text.style.ForegroundColorSpan.class).length);panel.select(1);text(root,lang.equals("ru")?"Загрузить ещё · история":"Load more · history").performClick();assertEquals(lang.equals("ru")?1:2,pages.get());panel.close();panel=null;}}
 @Test public void codexFilesAttachmentsAndDiffRuEn()throws Exception{check("codex");}
 @Test public void claudeFilesAttachmentsAndDiffRuEn()throws Exception{check("claude");}
 @Test public void geminiFilesAttachmentsAndDiffRuEn()throws Exception{check("gemini");}
 @Test public void openCodeFilesAttachmentsAndDiffRuEn()throws Exception{check("opencode");}
 @Test public void lateFilesystemResultCannotRepopulateClosedOrReassignedPanel()throws Exception{WorkspaceLanguage.select(a,"en");CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1);AgentProjectPanel.Backend slow=new AgentProjectPanel.Backend(){public byte[] read(String s,int max){started.countDown();for(;;)try{release.await();break;}catch(InterruptedException ignored){}return "OK\0/OLD_PROJECT\0aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\0 M SECRET_OLD.txt\0".getBytes();}public void close(){release.countDown();}};panel=new AgentProjectPanel(a,new WorkspaceStore.Session(),"/fixture",chat,slow);View root=panel.wrap(new LinearLayout(a),v->{},p->{});panel.select(2);assertTrue(started.await(2,TimeUnit.SECONDS));panel.close();idle();assertNull(text(root," M · SECRET_OLD.txt"));assertEquals(0,opens.get());}
 @Test public void failedHistoryNeverClaimsNoAttachmentsAndOffersExplicitRetry()throws Exception{WorkspaceLanguage.select(a,"ru");AgentProjectPanel.Chat failure=new AgentProjectPanel.Chat(){public boolean valid(){return true;}public List<JSONObject> rows(){return Collections.emptyList();}public boolean hasOlder(){return false;}public void older(){pages.incrementAndGet();}public String historyError(){return "Не удалось загрузить";}public void open(JSONObject f){fail();}public boolean jump(String k){return false;}public void observe(Runnable r){}public void close(){}};panel=new AgentProjectPanel(a,new WorkspaceStore.Session(),"/fake",failure,backend);View root=panel.wrap(new LinearLayout(a),v->{},p->{});panel.select(1);assertNotNull(text(root,"Не удалось загрузить"));assertNull(text(root,"Вложений нет"));text(root,"Повторить").performClick();assertEquals(1,pages.get());}

}
